/*
 * Horror Splash — хорор-заставка запуску для Lampa
 * Цегляна стіна тріскається й розлітається, з темряви виринає істота з червоними очима,
 * а внизу кривавим «хорор»-шрифтом з'являється назва.
 *
 * Підключення: Lampa → Налаштування → Розширення → Додати плагін → URL цього файлу.
 * Картинка вбудована у файл, окремі файли не потрібні.
 *
 * Налаштування (необов'язково) — задати до підключення плагіна:
 *   window.SKELETON_SPLASH_CONFIG = { title:'LAMPA', subtitle:'TV', speed:1.15, sound:true,
 *                                     image:'', webFont:true, renderScale:0.6667 };
 *   image   — свій URL картинки замість вбудованої
 *   webFont — підтягнути з Google Fonts кривавий шрифт Nosifer (якщо інтернету немає,
 *             літери малюються самим плагіном з краплями крові)
 *
 * Будь-яка клавіша / клік / дотик — пропустити заставку.
 */
(function () {
  'use strict';
  if (window.__skeleton_splash__) return;
  window.__skeleton_splash__ = true;

  var CFG = {
    title: 'LAMPA',
    subtitle: 'TV',
    speed: 1.15,         // 1 = ~8 c
    sound: true,         // синтезований звук (удари, обвал, гул, скрип)
    skippable: true,
    renderScale: 0.6667, // роздільність малювання (менше = швидше на слабких приставках)
    webFont: true,
    image: '',
    autoplay: true
  };
  var user = window.SKELETON_SPLASH_CONFIG;
  if (user) for (var key in user) if (user.hasOwnProperty(key)) CFG[key] = user[key];

  var IMG_DATA = 'data:image/jpeg;base64,';

  var W = 1920, H = 1080, CX = 1200, CY = 400, RX = 300, RY = 320;
  var LOGO_X = 1390, LOGO_Y = 770;
  var PI = Math.PI;
  // Часова шкала (секунди при speed = 1)
  var T = { k1: 0.6, k2: 1.1, crack: 1.0, brk: 2.4, fall: 3.1, logo: 4.6, fade: 7.7, end: 8.3 };
  // Положення очей на картинці (частки ширини/висоти)
  var EYES = [[0.5863, 0.3286], [0.668, 0.335]];

  var box, cv, g, rs, raf, running = false, dead = false, startMs = 0, fadeStart = 0, fired = {};
  var bricks, cracks, dust, P1, P2, P3, AC = null;
  var IMG = new Image(), imgReady = false;
  var fontOK = false, fontAsked = false, fontWait = [], DR = [];

  IMG.onload = function () { imgReady = true; };
  try { IMG.src = CFG.image || IMG_DATA; } catch (e0) {}

  /* ---------- утиліти ---------- */
  function cl(v, a, b) { return v < a ? a : (v > b ? b : v); }
  function ease(t) { return t < 0.5 ? 4 * t * t * t : 1 - Math.pow(-2 * t + 2, 3) / 2; }
  function smooth(t) { return t * t * (3 - 2 * t); }
  function lerp(a, b, t) { return a + (b - a) * t; }
  function seeded(seed) {
    var s = seed >>> 0;
    return function () { s = (s * 1664525 + 1013904223) >>> 0; return s / 4294967296; };
  }

  /* ---------- кривавий шрифт (Google Fonts → Nosifer) ---------- */
  function loadFont(cb) {
    if (!CFG.webFont || !document.head) { cb(); return; }
    fontWait.push(cb);
    if (fontAsked) return;
    fontAsked = true;
    var finished = false;
    function fin() {
      if (finished) return;
      finished = true;
      var q = fontWait; fontWait = [];
      for (var i = 0; i < q.length; i++) q[i]();
    }
    setTimeout(fin, 1800);
    try {
      var l = document.createElement('link');
      l.rel = 'stylesheet';
      l.href = 'https://fonts.googleapis.com/css2?family=Nosifer&display=block';
      l.onerror = fin;
      l.onload = function () {
        try {
          document.fonts.load('100px Nosifer', 'LAMPA TV').then(function (f) {
            fontOK = !!(f && f.length > 0); fin();
          }, fin);
        } catch (e) { fin(); }
      };
      document.head.appendChild(l);
    } catch (e2) { fin(); }
  }

  /* ---------- форма пролому ---------- */
  function lim(th) {
    return 1 + 0.10 * Math.sin(5 * th + P1) + 0.07 * Math.sin(9 * th + P2) + 0.04 * Math.sin(15 * th + P3);
  }
  function holeInfo(x, y) {
    var ex = (x - CX) / RX, ey = (y - CY) / RY;
    return Math.sqrt(ex * ex + ey * ey) / lim(Math.atan2(ey, ex));
  }

  /* ---------- підготовка сцени ---------- */
  function build() {
    var r = seeded(11), i, j;
    P1 = r() * 6.28; P2 = r() * 6.28; P3 = r() * 6.28;
    bricks = [];
    var bw = 128, bh = 64;
    for (var row = -1; row < Math.ceil(H / bh) + 1; row++) {
      var off = (Math.abs(row) % 2) ? -bw / 2 : 0;
      for (var col = -1; col < Math.ceil(W / bw) + 2; col++) {
        var x = col * bw + off, y = row * bh, mx = x + bw / 2, my = y + bh / 2;
        var inside = holeInfo(mx, my) < 0.92;
        var b = { x: x, y: y, mx: mx, my: my, hole: inside,
                  c: 'hsl(' + Math.round(10 + r() * 14) + ',' + Math.round(14 + r() * 14) + '%,' + Math.round(14 + r() * 9) + '%)' };
        if (inside) {
          var f = 1 + r() * 1.2;
          b.vx = (mx - CX) * f * 1.4;
          b.vy = (my - CY) * f * 1.1 - 180 - r() * 200;
          b.vz = 0.6 + r() * 1.8;
          b.vr = (r() - 0.5) * 8;
        } else {
          var dd = Math.sqrt((mx - CX) * (mx - CX) + (my - CY) * (my - CY));
          b.fd = 0.1 + dd / 1500 * 0.9 + r() * 0.35;
          b.fvx = (r() - 0.5) * 170;
          b.fr = (r() - 0.5) * 3;
        }
        bricks.push(b);
      }
    }
    cracks = [];
    for (i = 0; i < 10; i++) {
      var a = i / 10 * 2 * PI + (r() - 0.5) * 0.5;
      var px = CX + (r() - 0.5) * 40, py = CY + (r() - 0.5) * 40, pts = [[px, py]];
      for (j = 0; j < 14; j++) {
        a += (r() - 0.5) * 0.9;
        var st = 28 + r() * 34;
        px += Math.cos(a) * st; py += Math.sin(a) * st;
        pts.push([px, py]);
      }
      cracks.push(pts);
    }
    dust = [];
    for (i = 0; i < 36; i++) {
      var an = r() * 2 * PI, sp = 120 + r() * 520;
      dust.push({ x: CX + (r() - 0.5) * RX * 1.2, y: CY + (r() - 0.5) * RY * 1.2,
                  vx: Math.cos(an) * sp, vy: Math.sin(an) * sp * 0.7 - 40,
                  r: 28 + r() * 60, life: 1.2 + r() * 1.4 });
    }
  }

  /* ---------- звук (синтез WebAudio) ---------- */
  function audioInit() {
    if (!CFG.sound) return;
    try {
      var C = window.AudioContext || window.webkitAudioContext;
      if (C) { AC = new C(); if (AC.resume) AC.resume(); }
    } catch (e) { AC = null; }
  }
  function thud(vol, freq) {
    if (!AC) return;
    try {
      var n = AC.currentTime, o = AC.createOscillator(), gn = AC.createGain();
      o.type = 'sine';
      o.frequency.setValueAtTime(freq, n);
      o.frequency.exponentialRampToValueAtTime(30, n + 0.25);
      gn.gain.setValueAtTime(vol, n);
      gn.gain.exponentialRampToValueAtTime(0.001, n + 0.3);
      o.connect(gn); gn.connect(AC.destination);
      o.start(n); o.stop(n + 0.35);
    } catch (e) {}
  }
  function noise(dur, vol, cut) {
    if (!AC) return;
    try {
      var len = Math.floor(AC.sampleRate * dur), buf = AC.createBuffer(1, len, AC.sampleRate);
      var d = buf.getChannelData(0);
      for (var i = 0; i < len; i++) d[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / len, 2);
      var s = AC.createBufferSource(), f = AC.createBiquadFilter(), gn = AC.createGain();
      s.buffer = buf; f.type = 'lowpass'; f.frequency.value = cut; gn.gain.value = vol;
      s.connect(f); f.connect(gn); gn.connect(AC.destination); s.start();
    } catch (e) {}
  }
  function drone() {
    if (!AC) return;
    try {
      var n = AC.currentTime, f = AC.createBiquadFilter(), gn = AC.createGain();
      f.type = 'lowpass'; f.frequency.value = 220;
      gn.gain.setValueAtTime(0.0001, n);
      gn.gain.linearRampToValueAtTime(0.22, n + 1.2);
      gn.gain.linearRampToValueAtTime(0.0001, n + 5.5);
      f.connect(gn); gn.connect(AC.destination);
      [46, 46.8, 69].forEach(function (fr) {
        var o = AC.createOscillator(); o.type = 'sawtooth'; o.frequency.value = fr;
        o.connect(f); o.start(n); o.stop(n + 5.6);
      });
    } catch (e) {}
  }
  function sting() {
    if (!AC) return;
    try {
      var n = AC.currentTime, gn = AC.createGain();
      gn.gain.setValueAtTime(0.0001, n);
      gn.gain.exponentialRampToValueAtTime(0.14, n + 0.05);
      gn.gain.exponentialRampToValueAtTime(0.0001, n + 1.3);
      gn.connect(AC.destination);
      [1, 1.06, 1.41].forEach(function (m) {
        var o = AC.createOscillator(); o.type = 'sawtooth';
        o.frequency.setValueAtTime(700 * m, n);
        o.frequency.exponentialRampToValueAtTime(260 * m, n + 1.2);
        o.connect(gn); o.start(n); o.stop(n + 1.3);
      });
    } catch (e) {}
  }
  function fire(t) {
    if (!fired.k1 && t >= T.k1) { fired.k1 = 1; thud(0.7, 110); }
    if (!fired.k2 && t >= T.k2) { fired.k2 = 1; thud(0.9, 95); }
    if (!fired.rm && t >= 1.6) { fired.rm = 1; noise(0.8, 0.25, 300); }
    if (!fired.b && t >= T.brk) { fired.b = 1; noise(1.4, 0.9, 1400); thud(1, 70); drone(); }
    if (!fired.f && t >= T.fall) { fired.f = 1; noise(1.2, 0.5, 700); }
    if (!fired.l && t >= T.logo) { fired.l = 1; sting(); thud(0.8, 90); }
  }

  /* ---------- тряска ---------- */
  function bump(t, t0, amp, dur) { var d = t - t0; return (d >= 0 && d < dur) ? amp * (1 - d / dur) : 0; }
  function shakeAmp(t) {
    var a = bump(t, T.k1, 4, 0.25) + bump(t, T.k2, 6, 0.3);
    if (t > 1.5 && t < T.brk) a += 2 + (t - 1.5) / 0.9 * 9;
    if (t >= T.brk) a += 22 * Math.exp(-(t - T.brk) * 5);
    if (t >= T.fall && t < T.fall + 1.2) a += 5 * (1 - (t - T.fall) / 1.2);
    if (t >= T.logo && t < T.logo + 0.35) a += 6 * (1 - (t - T.logo) / 0.35);
    return a;
  }

  /* ---------- картинка: істота, що виринає ---------- */
  function imgRect() {
    var iw = IMG.naturalWidth || 1440, ih = IMG.naturalHeight || 900;
    var s = Math.max(W / iw, H / ih), dw = iw * s, dh = ih * s;
    return { x: (W - dw) / 2, y: -(dh - H) * 0.3, w: dw, h: dh };
  }
  function drawScene(t) {
    var tt = t - T.brk;
    if (tt < 0) return;
    var r = imgRect();
    var ex = r.x + r.w * (EYES[0][0] + EYES[1][0]) / 2, ey = r.y + r.h * (EYES[0][1] + EYES[1][1]) / 2;
    var z = 1 + 0.17 * ease(cl(tt / 6, 0, 1));
    var swx = Math.sin(tt * 0.9) * 7, swy = Math.cos(tt * 1.3) * 5;
    g.save();
    g.translate(ex + swx, ey + swy); g.scale(z, z); g.translate(-ex, -ey);
    g.fillStyle = '#040202'; g.fillRect(-500, -500, W + 1000, H + 1000);
    if (imgReady) g.drawImage(IMG, r.x, r.y, r.w, r.h);
    var dk = 1 - smooth(cl((tt - 0.2) / 2.8, 0, 1));
    if (dk > 0) { g.fillStyle = 'rgba(2,0,0,' + (0.94 * dk) + ')'; g.fillRect(-500, -500, W + 1000, H + 1000); }
    // червоне світіння очей: кілька миготінь, потім стабільна пульсація
    var open = smooth(cl((tt - 0.1) / 0.7, 0, 1));
    if (tt > 0.9 && tt < 1.05) open *= 0.2;
    if (tt > 1.5 && tt < 1.6) open *= 0.3;
    var pulse = (0.82 + 0.18 * Math.sin(tt * 8)) * open;
    if (pulse > 0) {
      var i, gr, gx, gy;
      g.globalCompositeOperation = 'lighter';
      gr = g.createRadialGradient(ex, ey + 40, 10, ex, ey + 40, 520);
      gr.addColorStop(0, 'rgba(150,0,0,' + (0.30 * pulse) + ')');
      gr.addColorStop(1, 'rgba(150,0,0,0)');
      g.fillStyle = gr; g.fillRect(ex - 560, ey - 480, 1120, 1120);
      for (i = 0; i < 2; i++) {
        gx = r.x + r.w * EYES[i][0]; gy = r.y + r.h * EYES[i][1];
        gr = g.createRadialGradient(gx, gy, 2, gx, gy, 95);
        gr.addColorStop(0, 'rgba(255,90,70,' + (0.95 * pulse) + ')');
        gr.addColorStop(0.35, 'rgba(255,0,0,' + (0.5 * pulse) + ')');
        gr.addColorStop(1, 'rgba(255,0,0,0)');
        g.fillStyle = gr; g.fillRect(gx - 100, gy - 100, 200, 200);
      }
      g.globalCompositeOperation = 'source-over';
    }
    g.restore();
  }

  function drawFog(t) {
    var tt = t - T.brk;
    if (tt < 0) return;
    var a = cl(tt / 2.2, 0, 1) * 0.12;
    for (var i = 0; i < 7; i++) {
      var x = ((i * 397 + t * (22 + i * 7)) % (W + 900)) - 450;
      var y = 760 + (i % 3) * 110 + Math.sin(t * 0.6 + i) * 34;
      var gr = g.createRadialGradient(x, y, 20, x, y, 420);
      gr.addColorStop(0, 'rgba(170,170,175,' + a + ')');
      gr.addColorStop(1, 'rgba(170,170,175,0)');
      g.fillStyle = gr;
      g.fillRect(x - 430, y - 430, 860, 860);
    }
  }

  /* ---------- стіна, уламки, пил ---------- */
  function drawWall(t) {
    var broken = t >= T.brk, a = shakeAmp(t) * 0.7;
    for (var i = 0; i < bricks.length; i++) {
      var b = bricks[i];
      if (b.hole && broken) continue;
      if (broken && t > T.fall) {
        var dt = t - T.fall - b.fd;
        if (dt > 0) {
          var yy = b.my + 1500 * dt * dt;
          if (yy > H + 120) continue;
          g.save();
          g.translate(b.mx + b.fvx * dt, yy); g.rotate(b.fr * dt);
          g.fillStyle = b.c; g.fillRect(-62, -30, 124, 60);
          g.fillStyle = 'rgba(255,170,150,0.06)'; g.fillRect(-62, -30, 124, 6);
          g.restore();
          continue;
        }
      }
      var ox = 0, oy = 0;
      if (b.hole && a > 0.5) { ox = (Math.random() - 0.5) * a; oy = (Math.random() - 0.5) * a; }
      g.fillStyle = b.c;
      g.fillRect(b.x + 2 + ox, b.y + 2 + oy, 124, 60);
      g.fillStyle = 'rgba(255,170,150,0.06)';
      g.fillRect(b.x + 2 + ox, b.y + 2 + oy, 124, 6);
    }
  }
  function drawCracks(t) {
    var p = cl((t - T.crack) / (T.brk - T.crack - 0.1), 0, 1);
    if (p <= 0) return;
    for (var pass = 0; pass < 2; pass++) {
      g.beginPath();
      for (var i = 0; i < cracks.length; i++) {
        var pts = cracks[i], n = pts.length, kk = p * (n - 1);
        g.moveTo(pts[0][0], pts[0][1]);
        for (var j = 1; j < n; j++) {
          if (j - 1 >= kk) break;
          var fr = Math.min(1, kk - (j - 1));
          g.lineTo(lerp(pts[j - 1][0], pts[j][0], fr), lerp(pts[j - 1][1], pts[j][1], fr));
        }
      }
      if (!pass) { g.strokeStyle = '#030101'; g.lineWidth = 6; }
      else { g.strokeStyle = 'rgba(255,40,30,' + (0.2 + 0.6 * p) + ')'; g.lineWidth = 2; }
      g.lineCap = 'round'; g.lineJoin = 'round';
      g.stroke();
    }
  }
  function drawDebris(t) {
    var tt = t - T.brk;
    if (tt > 1.3) return;
    var al = cl((1.3 - tt) / 0.6, 0, 1);
    for (var i = 0; i < bricks.length; i++) {
      var b = bricks[i];
      if (!b.hole) continue;
      g.save();
      g.globalAlpha = al;
      g.translate(b.mx + b.vx * tt, b.my + b.vy * tt + 1100 * tt * tt);
      g.rotate(b.vr * tt);
      var sc = 1 + b.vz * tt;
      g.scale(sc, sc);
      g.fillStyle = b.c;
      g.fillRect(-62, -30, 124, 60);
      g.restore();
    }
  }
  function drawDust(t) {
    var tt = t - T.brk;
    if (tt < 0) return;
    for (var i = 0; i < dust.length; i++) {
      var d = dust[i];
      if (tt > d.life) continue;
      var px = d.x + d.vx * tt, py = d.y + d.vy * tt, pr = d.r * (1 + tt * 1.5) * 1.6;
      var al = 0.22 * (1 - tt / d.life);
      var dg = g.createRadialGradient(px, py, 0, px, py, pr);
      dg.addColorStop(0, 'rgba(110,100,96,' + al + ')');
      dg.addColorStop(1, 'rgba(110,100,96,0)');
      g.fillStyle = dg;
      g.fillRect(px - pr, py - pr, pr * 2, pr * 2);
    }
    g.globalAlpha = 1;
  }

  /* ---------- назва «кривавим» шрифтом ---------- */
  function mkDrips(i) {
    var r = seeded(300 + i * 17), n = 1 + Math.floor(r() * 2.4), out = [];
    for (var j = 0; j < n; j++) {
      out.push({ px: 0.15 + r() * 0.7, len: 0.35 + r() * 0.8, w: 0.04 + r() * 0.04,
                 delay: r() * 1.4, dur: 1.4 + r() * 1.6 });
    }
    return out;
  }
  function drawDrips(i, x, w, baseY, t0, t, fs) {
    var rr = DR[i] || (DR[i] = mkDrips(i));
    for (var j = 0; j < rr.length; j++) {
      var d = rr[j], p = ease(cl((t - t0 - d.delay) / d.dur, 0, 1));
      if (p <= 0) continue;
      var len = d.len * fs * p, dx = x + w * d.px, wd = Math.max(3, d.w * fs);
      g.fillStyle = '#8e0a0a';
      g.beginPath(); g.rect(dx - wd / 2, baseY, wd, len);
      g.arc(dx, baseY + len, wd * 0.8, 0, PI * 2); g.fill();
    }
  }
  function bloodText(str, cx, cy, fs, fam, t, t0, step, drips) {
    var i, ws = [], tot = 0, gap = Math.round(fs * 0.04), x;
    g.font = fam.replace('%s', fs);
    for (i = 0; i < str.length; i++) { var w = g.measureText(str.charAt(i)).width; ws.push(w); tot += w + gap; }
    tot -= gap;
    x = cx - tot / 2;
    for (i = 0; i < str.length; i++) {
      var k = ease(cl((t - t0 - i * step) / 0.5, 0, 1));
      if (k > 0 && str.charAt(i) !== ' ') {
        var fl = Math.sin(t * 23 + i * 7) * Math.sin(t * 5.3 + i);
        var dim = (t - t0 < 1.6 && fl > 0.55) || fl > 0.96;
        g.save();
        g.globalAlpha = k * (dim ? 0.35 : 1);
        var jx = dim ? (Math.random() - 0.5) * 5 : 0;
        g.translate(x + ws[i] / 2 + jx, cy + (1 - k) * -40);
        if (drips) g.rotate(Math.sin(i * 12.9) * 0.05);
        var gr = g.createLinearGradient(0, -fs * 0.5, 0, fs * 0.5);
        gr.addColorStop(0, '#ff4a38'); gr.addColorStop(0.55, '#c10d0d'); gr.addColorStop(1, '#5a0000');
        g.textAlign = 'center'; g.textBaseline = 'middle';
        g.lineJoin = 'round'; g.lineWidth = Math.max(4, fs * 0.06);
        g.shadowColor = 'rgba(255,0,0,0.7)'; g.shadowBlur = 26;
        g.strokeStyle = '#120000'; g.strokeText(str.charAt(i), 0, 0);
        g.shadowBlur = 0;
        g.fillStyle = gr; g.fillText(str.charAt(i), 0, 0);
        g.restore();
        if (drips) {
          g.save(); g.globalAlpha = k * (dim ? 0.35 : 1);
          drawDrips(i + (fs < 90 ? 20 : 0), x, ws[i], cy + fs * 0.3, t0 + 0.4, t, fs);
          g.restore();
        }
      }
      x += ws[i] + gap;
    }
    return tot;
  }
  function drawLogo(t) {
    if (t < T.logo) return;
    var title = String(CFG.title || '').toUpperCase(), sub = String(CFG.subtitle || '').toUpperCase();
    var fam, fs = 150, tot, drips = !fontOK, kk = ease(cl((t - T.logo) / 0.8, 0, 1));
    fam = fontOK ? '%spx "Nosifer", Impact, sans-serif'
                 : '900 %spx Impact, Haettenschweiler, "Arial Black", sans-serif';
    g.save();
    // затемнення під написом для читабельності
    var bg = g.createRadialGradient(LOGO_X, LOGO_Y + 60, 40, LOGO_X, LOGO_Y + 60, 560);
    bg.addColorStop(0, 'rgba(0,0,0,' + (0.6 * kk) + ')'); bg.addColorStop(1, 'rgba(0,0,0,0)');
    g.fillStyle = bg; g.fillRect(LOGO_X - 600, LOGO_Y - 400, 1200, 900);
    // підбір розміру під ширину
    g.font = fam.replace('%s', fs);
    var m = 0, i;
    for (i = 0; i < title.length; i++) m += g.measureText(title.charAt(i)).width + fs * 0.04;
    if (m > 780) fs = Math.max(40, Math.floor(fs * 780 / m));
    tot = bloodText(title, LOGO_X, LOGO_Y, fs, fam, t, T.logo, 0.12, drips);
    if (sub) bloodText(sub.split('').join(' '), LOGO_X, LOGO_Y + fs * (drips ? 1.0 : 1.15), Math.round(fs * 0.5), fam, t, T.logo + 0.8, 0.14, drips);
    g.restore();
  }

  /* ---------- кадр ---------- */
  function render(t) {
    g.setTransform(rs, 0, 0, rs, 0, 0);
    g.globalAlpha = 1;
    g.fillStyle = '#050303'; g.fillRect(0, 0, W, H);
    var amp = shakeAmp(t), broken = t >= T.brk;
    g.save();
    if (amp > 0.2) g.translate((Math.random() - 0.5) * 2 * amp, (Math.random() - 0.5) * 2 * amp);
    if (broken) drawScene(t);
    drawWall(t);
    if (broken) { drawDebris(t); drawDust(t); drawFog(t); } else { drawCracks(t); }
    g.restore();
    drawLogo(t);
    var vg = g.createRadialGradient(W / 2, 540, 380, W / 2, 540, 1250);
    vg.addColorStop(0, 'rgba(0,0,0,0)'); vg.addColorStop(1, 'rgba(0,0,0,0.8)');
    g.fillStyle = vg; g.fillRect(0, 0, W, H);
    var fl = t - T.brk;
    if (fl >= 0 && fl < 0.35) { g.fillStyle = 'rgba(255,210,200,' + (0.9 * (1 - fl / 0.35)) + ')'; g.fillRect(0, 0, W, H); }
    if (t < 0.5) { g.fillStyle = 'rgba(0,0,0,' + (1 - t / 0.5) + ')'; g.fillRect(0, 0, W, H); }
  }

  /* ---------- життєвий цикл ---------- */
  function loop() {
    if (!running) return;
    var now = Date.now(), t = (now - startMs) / 1000 * CFG.speed, f;
    if (fadeStart) {
      f = (now - fadeStart) / 300;
      if (f >= 1) { stop(); return; }
      box.style.opacity = String(1 - f);
    } else if (t >= T.fade) {
      f = (t - T.fade) / (T.end - T.fade);
      if (f >= 1) { stop(); return; }
      box.style.opacity = String(1 - f);
    }
    fire(t);
    render(Math.min(t, T.end));
    raf = requestAnimationFrame(loop);
  }
  function skip() {
    if (dead) return;
    if (!running) { stop(); return; }
    if (!fadeStart) fadeStart = Date.now();
  }
  function onKey(e) {
    if (!CFG.skippable) return;
    if (e.preventDefault) e.preventDefault();
    if (e.stopPropagation) e.stopPropagation();
    skip();
  }
  function stop() {
    dead = true; running = false;
    try { cancelAnimationFrame(raf); } catch (e) {}
    document.removeEventListener('keydown', onKey, true);
    if (box && box.parentNode) box.parentNode.removeChild(box);
    try { if (AC && AC.close) AC.close(); } catch (e2) {}
    AC = null;
  }
  function play() {
    if (running) return;
    dead = false; fadeStart = 0; fired = {}; DR = [];
    build();
    rs = CFG.renderScale;
    box = document.createElement('div');
    box.id = 'skeleton-splash';
    box.style.cssText = 'position:fixed;left:0;top:0;width:100%;height:100%;background:#000;z-index:2147483647;opacity:1;';
    cv = document.createElement('canvas');
    cv.width = Math.round(W * rs); cv.height = Math.round(H * rs);
    cv.style.cssText = 'width:100%;height:100%;display:block;object-fit:contain;';
    box.appendChild(cv);
    document.body.appendChild(box);
    g = cv.getContext('2d');
    if (CFG.skippable) {
      document.addEventListener('keydown', onKey, true);
      box.addEventListener('click', skip);
      box.addEventListener('touchstart', skip);
    }
    // стартуємо, коли готові шрифт і картинка (але не довше ~2 с)
    var waited = 0;
    loadFont(function begin() {
      (function go() {
        if (dead) return;
        if (!imgReady && waited < 2000) { waited += 50; setTimeout(go, 50); return; }
        audioInit();
        running = true;
        startMs = Date.now();
        raf = requestAnimationFrame(loop);
      })();
    });
  }

  window.SkeletonSplash = { play: play, skip: skip, config: CFG };

  if (CFG.autoplay) {
    if (document.body) play();
    else document.addEventListener('DOMContentLoaded', play);
  }
})();
